(** ** What this board establishes

    171 of 180 arms of the certificate are re-derived by the kernel and
    sound: each [sound_*] is a theorem that the machine, from that arm's
    left-hand side and against any tail the flags permit, reaches the arm's
    right-hand side in exactly the certificate's step count. *)

(** ** The closure: a counter that adds 3 per visit ([LadderCheckStepTr])

    [LadderCheck]'s class split is for a step of 1; this family adds 3
    per anchor visit in base 4, and 3 divides 4 - 1, so the value
    mod 3 is the digit sum mod 3 and depends on the phase alone
    ([cres]).  The split is on the low digit: 1 no-carry arm(s), the
    carry arms at threshold 0 stride 1, and the fill arms at
    threshold 0 stride 1 from each phase's one top string
    ([utop]).  Every arm is a [LadderNest] segment program. *)
From BBB4.Checkers Require Import LadderCheckStepTr.

(** *** The inner rules: what the nested arms iterate *)
Definition nlad_1RB0RA_1RC1RD_1LD0LC_1RA1LC : list (LRule * list rstep) :=
  [].
Definition nrules_1RB0RA_1RC1RD_1LD0LC_1RA1LC : list LRule := map fst nlad_1RB0RA_1RC1RD_1LD0LC_1RA1LC.
Local Notation nrules := nrules_1RB0RA_1RC1RD_1LD0LC_1RA1LC.

Lemma nladder_ok_1RB0RA_1RC1RD_1LD0LC_1RA1LC : check_ladder tm [] nlad_1RB0RA_1RC1RD_1LD0LC_1RA1LC = true.
